raw = data[target_epc][0]

series = parse_points(raw)

fig, ax = plt.subplots(figsize=(11, 6), dpi=150)

# 自动取色, 序列多也不怕撞色
cmap = plt.get_cmap('tab10')

for i, (key, pts) in enumerate(sorted(series.items())):
    x = [p[0] for p in pts]
    y = [p[1] for p in pts]
    ax.plot(x, y, marker='o', markersize=4, linewidth=1.6,
            color=cmap(i % 10), label=f'{key:g}', zorder=3)

# ax.set_title(r'$\Delta\phi$ at different frequencies', fontsize=15, pad=12)
ax.set_title(r'$\phi$ at different frequencies', fontsize=15, pad=12)
ax.set_xlabel('Transmit Power (dBm)', fontsize=14)
# ax.set_ylabel(r'$\Delta\phi$ (rad)', fontsize=14)
ax.set_ylabel(r'$\phi$ (rad)', fontsize=14)
ax.tick_params(axis='both', labelsize=12)
ax.grid(True, linestyle='--', alpha=0.4, zorder=0)
ax.legend(title='Frequencies', fontsize=11, title_fontsize=12,
          loc='best', framealpha=0.95)

for s in ['top', 'right']:
    ax.spines[s].set_visible(False)

plt.tight_layout()
# plt.show()
out_path = f"./figures/Phase_Ptx_Image/{target_epc}/{time.time()}.png"
os.makedirs(os.path.dirname(out_path), exist_ok=True)   # ← 这行是关键
plt.savefig(out_path, dpi=150, bbox_inches='tight')

